/* eslint-env mocha */
import { expect } from 'chai';
import createFillinProps from './createFillinProps';


describe('createFillinProps-->', () => {
  it('returns a function', () => {
    expect(typeof createFillinProps()).to.equal('function');
  }); // end it

  it('takes in an object and returns it when returned func is invoked', () => {
    const fillInProps = createFillinProps({ someProp1: 'a', someProp: 2 });
    expect(fillInProps()).to.deep.equal({ someProp1: 'a', someProp: 2 });
  }); // end it

  it('accepts an object and overwrites key/values passed into the returned func', () => {
    const fillInProps = createFillinProps({ someProp1: 'a', someProp: 2 });
    expect(fillInProps({ someProp: 'PIZZA' })).to.deep.equal({ someProp1: 'a', someProp: 'PIZZA' });
  }); // end it
}); // end describe